from pathlib import Path
from html import escape as E
import json
ROOT=Path(__file__).resolve().parents[1]
D=json.loads((ROOT/'content.json').read_text())
STYLE='''@page{size:A4;margin:16mm 15mm 17mm}*{box-sizing:border-box}body{margin:0;color:#24313c;font-family:Arial,sans-serif;font-size:10pt;line-height:1.55}h1,h2,h3{color:#173f5b;line-height:1.25}h1{font-size:25pt;margin:0 0 6mm}h2{font-size:18pt;margin:0 0 5mm}h3{font-size:11pt;margin:4mm 0 2mm}.kicker{font-size:8pt;color:#956424;letter-spacing:1pt;font-weight:bold;margin:0 0 4mm}.cover{page-break-after:always;padding:15mm 2mm}.cover img{height:100mm;max-width:170mm;object-fit:contain;display:block;margin:4mm auto 8mm}.cover p{font-size:11pt;color:#65717c;line-height:1.8}.meta{display:flex;gap:7mm;border-bottom:1px solid #ddd;padding-bottom:4mm;margin-bottom:5mm;font-size:9pt;color:#65717c}.recipe{page-break-before:always}.ingredients{display:grid;grid-template-columns:1fr 1fr;column-gap:8mm}.group{break-inside:avoid}.ingredients ul{padding-left:4mm;margin:0}.ingredients li{font-size:9pt;margin:1mm 0}.steps{padding-left:5mm}.steps li{margin-bottom:3mm;break-inside:avoid;font-size:9pt}.steps strong{display:block;color:#173f5b}.note{font-size:8pt;background:#f8f3eb;padding:3mm 4mm;border-left:2px solid #b59052;margin:4mm 0;line-height:1.7;break-inside:avoid}.notes-list{padding-left:4mm;font-size:8pt;color:#65717c}.allergens{font-size:8pt;color:#80551b}.guide-section{break-inside:avoid;margin:7mm 0}.guide-section p,.guide-section li{font-size:10pt;line-height:1.8}.guide-image{max-width:100%;height:75mm;object-fit:cover;border-radius:3mm}.sources{font-size:8pt;line-height:1.9;overflow-wrap:anywhere}.tag-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:5mm}.tag{height:58mm;border:1px dashed #b58b47;border-radius:3mm;padding:8mm 4mm;text-align:center;break-inside:avoid;display:flex;align-items:center;justify-content:center;flex-direction:column}.tag span{color:#956424;font-size:18pt}.tag h2{font-size:14pt;margin:3mm 0}.tag p{font-size:9pt;margin:0;color:#65717c}.tag small{font-size:8pt;margin-top:4mm;color:#956424}a{color:#173f5b}'''
def html(title,body):return f'<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>{E(title)}</title><style>{STYLE}</style><body>{body}</body></html>'
def cover(title,subtitle,img):return f'<section class="cover"><p class="kicker">MINHA COZINHA • MINI PANETONES</p><h1>{E(title)}</h1><p>{E(subtitle)}</p><img src="../../assets/{img}" alt=""><div class="note">Receitas adaptadas e variações próprias, sem teste prático de cozinha nesta produção. Faça um primeiro preparo para ajustar forno, forma e rendimento. As imagens são ilustrativas. As aulas públicas de apoio podem demonstrar fórmulas diferentes.</div><p>Consulte a área de membros para ajustar quantidades, montar a lista de compras e acompanhar as aulas.</p></section>'
def recipe(r):
 groups=''.join('<div class="group"><h3>'+E(g['title'])+'</h3><ul>'+''.join(f'<li><strong>{str(i["amount"]).replace(".",",")} {i["unit"]}</strong> {E(i["name"])}</li>' for i in g['items'])+'</ul></div>' for g in r['groups'])
 steps=''.join(f'<li><strong>{E(s["title"])}</strong>{E(s["text"])}</li>' for s in r['steps'])
 return f'<article class="recipe"><p class="kicker">{E(r["category"].upper())} • {r["id"].upper()}</p><h2>{E(r["name"])}</h2><div class="meta"><span>Rendimento estimado: {r["yield"]} unidades</span><span>{E(r["time"])}</span></div><p>{E(r["description"])}</p><div class="ingredients">{groups}</div><h3>Modo de preparo</h3><ol class="steps">{steps}</ol><p class="allergens">Alergênicos: {E(", ".join(r["allergens"]))}. Confira também os rótulos dos ingredientes.</p><div class="note">'+E(r['notes'][0])+'</div><ul class="notes-list">'+''.join('<li>'+E(n)+'</li>' for n in r['notes'][1:])+f'</ul><p class="sources">Vídeo público de apoio: https://www.youtube.com/watch?v={r["video"]}<br>Referências gerais e orientações no guia de cuidados da área de membros.</p></article>'
for key,recipes,title,subtitle,img in [('80-receitas',D['recipes'],'80 receitas de mini panetones e chocotones','Para fazer em casa, presentear e vender. Uma massa base e 80 versões de sabores, recheios e acabamentos.','hero-mockup.png'),('biscoitos-natal',D['cookies'],'12 biscoitos de Natal','Variações de massa amanteigada para o café, os presentes e as lembrancinhas.','bonus-biscoitos.jpg'),('sobremesas-copinhos',D['cups'],'10 sobremesas no copinho','Cremes e combinações em porções individuais.','bonus-copinhos.jpg')]:
 (ROOT/'downloads'/f'{key}.html').write_text(html(title,cover(title,subtitle,img)+''.join(recipe(r) for r in recipes)))
for key in ['decoracoes','embalagens','vendas']:
 g=D['guides'][key]
 body='<p class="kicker">BÔNUS DA SUA COLEÇÃO</p><h1>'+E(g['title'])+'</h1><p>'+E(g['subtitle'])+'</p><img class="guide-image" src="../'+g['image']+'" alt="">'
 for s in g['sections']:body+='<section class="guide-section"><h2>'+E(s['title'])+'</h2><p>'+E(s['text'])+'</p>'+('<ul>'+''.join('<li>'+E(t)+'</li>' for t in s.get('list',[]))+'</ul>' if s.get('list') else '')+'</section>'
 if key=='vendas':
  body+='<h2>Mensagens para adaptar e enviar</h2>'
  for m in g['messages']:body+='<section class="guide-section"><h3>'+E(m['title'])+'</h3><p>'+E(m['text'])+'</p></section>'
 if g['videos']:body+='<h2>Aulas públicas de apoio</h2><div class="sources">'+''.join('https://www.youtube.com/watch?v='+v+'<br>' for v in g['videos'])+'</div>'
 body+='<div class="note">Imagens ilustrativas geradas por IA. A coleção e os guias não substituem a validação do seu processo, do rendimento e da conservação.</div>'
 (ROOT/'downloads'/f'guia-{key}.html').write_text(html(g['title'],body))
messages=['Feito com carinho','Um Natal cheio de sabor','Para alguém especial','Um presente da minha cozinha']
body='<div class="tag-grid">'+''.join('<article class="tag"><span>✦</span><h2>'+m+'</h2><p>Um Natal cheio de carinho<br>e coisas gostosas!</p><small>Com carinho, __________________</small></article>' for m in messages*3)+'</div>'
(ROOT/'downloads'/'tags-natal.html').write_text(html('Tags de Natal',body))
print('7 documentos HTML prontos para exportação PDF')
